import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Testing & QA","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/testing.md","filePath":"deployment/testing.md"}`),a={name:`deployment/testing.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="testing-qa" tabindex="-1">Testing &amp; QA <a class="header-anchor" href="#testing-qa" aria-label="Permalink to &quot;Testing &amp; QA&quot;">​</a></h1><p>Quality Assurance is a critical component of the TechyNews development lifecycle. All code changes must be verified before deployment.</p><h2 id="test-suites" tabindex="-1">Test Suites <a class="header-anchor" href="#test-suites" aria-label="Permalink to &quot;Test Suites&quot;">​</a></h2><h3 id="_1-backend-testing-phpunit" tabindex="-1">1. Backend Testing (PHPUnit) <a class="header-anchor" href="#_1-backend-testing-phpunit" aria-label="Permalink to &quot;1. Backend Testing (PHPUnit)&quot;">​</a></h3><p>We use PHPUnit for testing Laravel controllers, services, and models.</p><ul><li><strong>Run Tests:</strong> <code>php artisan test</code></li><li><strong>Focus:</strong> Ensure API endpoints return expected data, database interactions are correct, and AI services handle edge cases gracefully.</li></ul><h3 id="_2-frontend-testing-jest-react-testing-library" tabindex="-1">2. Frontend Testing (Jest / React Testing Library) <a class="header-anchor" href="#_2-frontend-testing-jest-react-testing-library" aria-label="Permalink to &quot;2. Frontend Testing (Jest / React Testing Library)&quot;">​</a></h3><p>React components and utility functions are tested using Jest and React Testing Library.</p><ul><li><strong>Run Tests:</strong> <code>npm test</code> or <code>npm run test</code></li><li><strong>Focus:</strong> Component rendering, state management, and user interactions.</li></ul><h3 id="_3-end-to-end-testing-playwright-cypress" tabindex="-1">3. End-to-End Testing (Playwright / Cypress) <a class="header-anchor" href="#_3-end-to-end-testing-playwright-cypress" aria-label="Permalink to &quot;3. End-to-End Testing (Playwright / Cypress)&quot;">​</a></h3><p>E2E testing is employed to simulate real user journeys.</p><ul><li><strong>Run Tests:</strong> <code>npx playwright test</code> (or <code>npm run test:e2e</code> for Cypress).</li><li><strong>Focus:</strong> Complete workflows, such as navigating the site, reading an article, and toggling themes.</li></ul><h2 id="the-qa-process" tabindex="-1">The QA Process <a class="header-anchor" href="#the-qa-process" aria-label="Permalink to &quot;The QA Process&quot;">​</a></h2><p>Before any code is pushed to production, the developer or AI agent must follow these steps:</p><ol><li>Ensure the local build succeeds (<code>npm run build</code>).</li><li>Run the full test suite (Backend, Frontend, E2E).</li><li>Conduct a manual smoke test if the change impacts critical UI components.</li><li>Only if all checks pass, generate a Pull Request or push to the <code>main</code> branch.</li></ol>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};